(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const status = document.getElementById('status');
  const bgmToggle = document.getElementById('bgmToggle');
  const bgmVolumeSlider = document.getElementById('bgmVolume');
  const sfxVolumeSlider = document.getElementById('sfxVolume');
  const bgmVolumeValue = document.getElementById('bgmVolumeValue');
  const sfxVolumeValue = document.getElementById('sfxVolumeValue');
  const W = canvas.width, H = canvas.height;
  const GAME_TIME = 30;
  const difficulties = {
    "初級": { radius: 35, maxMisses: 5 },
    "中級": { radius: 23, maxMisses: 3 },
    "上級": { radius: 12, maxMisses: 1 }
  };
  let state = "title";
  let difficulty = "中級";
  let hits = 0, misses = 0;
  let startTime = 0, coreStart = 0, countdownStart = 0;
  let target = null;
  let endReason = "time";
  let buttons = {};
  // Web Audioで効果音を生成（外部音声ファイル不要）
  let audioCtx = null;
  let lastCountdownNumber = null;
  let bgmEnabled = true;
  let bgmVolume = 0.30;
  let sfxVolume = 1.0;
  const bgmAudio = new Audio("data:audio/mpeg;base64,");
  bgmAudio.preload = "auto";
  bgmAudio.volume = bgmVolume;
  bgmAudio.loop = false;
  let bgmStarted = false;
  function initAudio() {
    if (!audioCtx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) audioCtx = new AudioContextClass();
    }
    if (audioCtx && audioCtx.state === "suspended") audioCtx.resume();
  }
  function tone(freq, duration=0.1, type="sine", volume=0.07, endFreq=null, delay=0) {
    if (!audioCtx) return;
    const t = audioCtx.currentTime + delay;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(1,endFreq), t+duration);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, Math.min(volume * 3.0, 0.60) * sfxVolume), t+0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t+duration);
    osc.connect(gain); gain.connect(audioCtx.destination);
    osc.start(t); osc.stop(t+duration+0.02);
  }
  function startBgm(restart=false) {
    if (!bgmEnabled) return;
    bgmAudio.volume = bgmVolume;
    if (restart || !bgmStarted) {
      bgmAudio.pause();
      bgmAudio.currentTime = 0;
      bgmStarted = true;
    }
    const promise = bgmAudio.play();
    if (promise && promise.catch) promise.catch(() => {});
  }
  function stopBgm() {
    bgmAudio.pause();
  }
  bgmAudio.addEventListener("ended", () => { bgmStarted = false; });
  bgmVolumeSlider.addEventListener("input", () => {
    bgmVolume = Number(bgmVolumeSlider.value) / 100;
    bgmAudio.volume = bgmVolume;
    bgmVolumeValue.textContent = `${bgmVolumeSlider.value}%`;
  });
  sfxVolumeSlider.addEventListener("input", () => {
    sfxVolume = Number(sfxVolumeSlider.value) / 100;
    sfxVolumeValue.textContent = `${sfxVolumeSlider.value}%`;
  });
  bgmToggle.addEventListener("click", () => {
    initAudio();
    bgmEnabled = !bgmEnabled;
    bgmToggle.textContent = `♪ BGM：${bgmEnabled ? "ON" : "OFF"}`;
    bgmToggle.setAttribute("aria-pressed", String(bgmEnabled));
    if (bgmEnabled) {
      if (state === "playing" || state === "core") startBgm(!bgmStarted);
    } else stopBgm();
  });
  function playSound(kind) {
    if (!audioCtx) return;
    if (kind === "count") tone(660,0.12,"sine",0.12);
    else if (kind === "start") { tone(520,0.13,"triangle",0.07); tone(780,0.2,"triangle",0.07,null,0.13); }
    else if (kind === "hit") { tone(920,0.07,"square",0.045,620); tone(1240,0.055,"sine",0.035,null,0.035); }
    else if (kind === "miss") tone(210,0.16,"sawtooth",0.045,100);
    else if (kind === "overload") { tone(170,0.7,"sawtooth",0.08,42); tone(330,0.55,"triangle",0.055,75,0.08); }
    else if (kind === "activate") { tone(260,0.45,"sine",0.07,900); tone(520,0.6,"triangle",0.06,1500,0.12); tone(1040,0.8,"sine",0.04,1700,0.24); }
  }

  function roundRect(x,y,w,h,r,fill,stroke="#5ae6ff") {
    ctx.beginPath();
    ctx.roundRect(x,y,w,h,r);
    ctx.fillStyle = fill; ctx.fill();
    if (stroke) { ctx.lineWidth=2; ctx.strokeStyle=stroke; ctx.stroke(); }
  }
  function text(str, x, y, size=28, color="#f0f5ff", align="center", weight="normal") {
    ctx.fillStyle=color; ctx.font=`${weight} ${size}px "Yu Gothic", Meiryo, sans-serif`;
    ctx.textAlign=align; ctx.textBaseline="middle"; ctx.fillText(str,x,y);
  }
  function background() {
    ctx.fillStyle="#0c1120"; ctx.fillRect(0,0,W,H);
    ctx.strokeStyle="#141e32"; ctx.lineWidth=1;
    for(let x=0;x<W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
    for(let y=0;y<H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  }
  function spawnTarget() {
    const r = difficulties[difficulty].radius;
    target = { x: r+10+Math.random()*(W-2*r-20), y: 100+r+Math.random()*(H-2*r-120), r };
  }
  function drawTarget(t) {
    ctx.beginPath(); ctx.arc(t.x,t.y,t.r+5,0,Math.PI*2);
    ctx.strokeStyle="#ff4b64"; ctx.lineWidth=2; ctx.stroke();
    ctx.beginPath(); ctx.arc(t.x,t.y,t.r,0,Math.PI*2);
    ctx.fillStyle="#eb4155"; ctx.fill();
    ctx.beginPath(); ctx.arc(t.x,t.y,Math.max(3,Math.floor(t.r/2)),0,Math.PI*2);
    ctx.fillStyle="#f0f5ff"; ctx.fill();
    ctx.beginPath(); ctx.arc(t.x,t.y,Math.max(2,Math.floor(t.r/5)),0,Math.PI*2);
    ctx.fillStyle="#ff4b64"; ctx.fill();
  }
  function button(label,x,y,w,h,selected=false) {
    roundRect(x,y,w,h,12,selected?"#2879bd":"#142d4b");
    text(label,x+w/2,y+h/2,23,"#f0f5ff");
    return {x,y,w,h};
  }
  function inside(p,x,y) { return p.x>=x.x && p.x<=x.x+x.w && p.y>=x.y && p.y<=x.y+x.h; }
  function drawTitle() {
    background();
    text("CORE AIM TRAINER",W/2,115,48,"#5ae6ff","center","bold");
    text("ターゲットをクリックして撃て！",W/2,185,26);
    text("難易度を選択",W/2,245,26);
    buttons.easy=button("初級",170,290,170,65,difficulty==="初級");
    buttons.normal=button("中級",365,290,170,65,difficulty==="中級");
    buttons.hard=button("上級",560,290,170,65,difficulty==="上級");
    text("制限時間：30秒",W/2,405,21,"#9aabc4");
    buttons.start=button("ゲームスタート",335,475,230,65);
    status.textContent = `難易度：${difficulty}`;
  }
  function startGame() {
    hits=0; misses=0; target=null;
    countdownStart=performance.now();
    lastCountdownNumber=null;
    state="countdown";
    stopBgm();
  }
  function drawCountdown(now) {
    background();
    const elapsed=(now-countdownStart)/1000;
    const number=3-Math.floor(elapsed);
    text("準備して！",W/2,H/2-100,34,"#9aabc4");
    if(elapsed<3) {
      if (number !== lastCountdownNumber) { playSound("count"); lastCountdownNumber=number; }
      text(String(number),W/2,H/2,112,"#5ae6ff","center","bold");
      text("START",W/2,H/2+100,28,"#f0f5ff","center","bold");
      status.textContent=`スタートまで ${number} 秒`;
    } else {
      startTime=now;
      playSound("start");
      state="playing";
      if (bgmEnabled) startBgm(true);
      spawnTarget();
    }
  }
  function drawGame(now) {
    background();
    const remaining=Math.max(0,GAME_TIME-(now-startTime)/1000);
    text(`TIME: ${remaining.toFixed(1)}`,100,35,27);
    text(`HITS: ${hits}`,350,35,27,"#5ae6ff");
    text(`MISSES: ${misses}`,600,35,27,"#ff4b64");
    text(`難易度：${difficulty}`,780,80,20);
    if(target) drawTarget(target);
    status.textContent = `残り ${remaining.toFixed(1)} 秒`;
    if(remaining<=0){stopBgm();state="result";endReason="time";}
  }
  function drawSemi(cx,cy,r,upper,fill) {
    ctx.save();
    ctx.beginPath();
    if(upper){ctx.arc(cx,cy,r,Math.PI,Math.PI*2);}
    else {ctx.arc(cx,cy,r,0,Math.PI);}
    ctx.lineTo(cx,cy); ctx.closePath();
    // Simple, smooth metallic shell
    const metal=ctx.createLinearGradient(cx-r,cy-r,cx+r,cy+r);
    metal.addColorStop(0,"#52616b");
    metal.addColorStop(0.22,"#dce4e8");
    metal.addColorStop(0.48,"#87959e");
    metal.addColorStop(0.68,"#eaf0f3");
    metal.addColorStop(1,"#47545d");
    ctx.fillStyle=metal; ctx.fill();
    ctx.lineWidth=5;ctx.strokeStyle="#26343d";ctx.stroke();
    ctx.lineWidth=2;ctx.strokeStyle="rgba(255,255,255,0.75)";ctx.stroke();
    ctx.restore();
  }
  function drawCore(now) {
    const elapsed=(now-coreStart)/1000;
    const progress=Math.min(elapsed/5,1);
    const cx=W/2, cy=H/2, r=105;
    ctx.fillStyle="#030712";ctx.fillRect(0,0,W,H);

    // Faint sci-fi background
    ctx.strokeStyle="#102b49";ctx.lineWidth=1;
    for(let x=0;x<W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
    for(let y=0;y<H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}

    const pulse=(Math.sin(elapsed*10)+1)/2;
    const closeProgress=Math.min(progress/0.4,1);
    const gap=115*(1-closeProgress);
    const topY=cy-gap/2, bottomY=cy+gap/2;

    // Expanding ring
    const ringR=70+elapsed*58;
    if(ringR<360){
      ctx.beginPath();ctx.arc(cx,cy,ringR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(65,165,255,${Math.max(.08,1-progress)})`;ctx.lineWidth=2;ctx.stroke();
    }

    // Core glow behind the shells
    const glow=ctx.createRadialGradient(cx,cy,4,cx,cy,150);
    glow.addColorStop(0,`rgba(225,250,255,${0.38+progress*0.48})`);
    glow.addColorStop(0.28,`rgba(75,190,255,${0.32+progress*0.42})`);
    glow.addColorStop(0.68,`rgba(20,100,255,${0.12+progress*0.2})`);
    glow.addColorStop(1,"rgba(20,100,255,0)");
    ctx.fillStyle=glow;ctx.fillRect(cx-180,cy-180,360,360);

    // Stronger blue-white bloom around the core
    ctx.save();
    ctx.globalCompositeOperation="lighter";
    const bloom=ctx.createRadialGradient(cx,cy,8,cx,cy,260+progress*180);
    bloom.addColorStop(0,`rgba(255,255,255,${0.16+progress*0.36})`);
    bloom.addColorStop(0.18,`rgba(150,225,255,${0.20+progress*0.42})`);
    bloom.addColorStop(0.5,`rgba(35,140,255,${0.12+progress*0.3})`);
    bloom.addColorStop(1,"rgba(20,90,255,0)");
    ctx.fillStyle=bloom;ctx.fillRect(0,0,W,H);
    ctx.restore();

    // Metallic core is drawn first, so the shells sit in front of it
    const coreRadius = 27; // コア本体の大きさは演出中も一定
    const coreGlow = ctx.createRadialGradient(cx,cy,2,cx,cy,coreRadius+30);
    coreGlow.addColorStop(0,"rgba(255,255,255,1)");
    coreGlow.addColorStop(0.25,"rgba(180,240,255,0.98)");
    coreGlow.addColorStop(0.6,"rgba(65,175,255,0.75)");
    coreGlow.addColorStop(1,"rgba(35,115,255,0)");
    ctx.fillStyle=coreGlow;
    ctx.beginPath();ctx.arc(cx,cy,coreRadius+30,0,Math.PI*2);ctx.fill();

    const coreMetal=ctx.createRadialGradient(cx-coreRadius*0.38,cy-coreRadius*0.42,2,cx,cy,coreRadius);
    coreMetal.addColorStop(0,"#ffffff");
    coreMetal.addColorStop(0.18,"#d9e8ef");
    coreMetal.addColorStop(0.38,"#718795");
    coreMetal.addColorStop(0.58,"#f7fdff");
    coreMetal.addColorStop(0.78,"#526775");
    coreMetal.addColorStop(1,"#172b3a");
    ctx.beginPath();ctx.arc(cx,cy,coreRadius,0,Math.PI*2);
    ctx.fillStyle=coreMetal;ctx.fill();
    ctx.lineWidth=3;ctx.strokeStyle="#f5fcff";ctx.stroke();
    ctx.beginPath();ctx.arc(cx,cy,coreRadius*0.58,0,Math.PI*2);
    ctx.fillStyle=`rgba(220,249,255,${0.78+0.22*pulse})`;ctx.fill();
    ctx.lineWidth=2;ctx.strokeStyle="rgba(255,255,255,0.95)";ctx.stroke();

    // Plain upper and lower metal hemispheres in front of the core
    drawSemi(cx,topY,r,true,"#8b9ca7");
    drawSemi(cx,bottomY,r,false,"#8b9ca7");

    // Blue-white light ramps up after the core closes
    if(progress>=0.4){
      const lightProgress=(progress-0.4)/0.6;
      const alpha=0.16+0.84*lightProgress;
      const flash=ctx.createRadialGradient(cx,cy,5,cx,cy,Math.max(W,H)*0.7);
      flash.addColorStop(0,`rgba(245,252,255,${alpha})`);
      flash.addColorStop(0.25,`rgba(125,205,255,${alpha*0.82})`);
      flash.addColorStop(0.7,`rgba(45,130,255,${alpha*0.42})`);
      flash.addColorStop(1,`rgba(35,95,255,${alpha*0.3})`);
      ctx.fillStyle=flash;ctx.fillRect(0,0,W,H);
    }


    if(progress<0.4) text("CORE OVERLOAD!",cx,cy+175,42,"#5ae6ff","center","bold");
    else text("CORE ACTIVATED",cx,cy+175,42,"#ffffff","center","bold");

    status.textContent = `CORE OVERLOAD • ${(Math.max(0,5-elapsed)).toFixed(1)}秒`;
    if(elapsed>=5){if(state==="core"){playSound("activate");state="result";}}
  }
  function drawResult() {
    background();
    const total=hits+misses;
    const accuracy=total>0?hits/total*100:0;
    text("RESULT",W/2,130,52,"#5ae6ff","center","bold");
    text(`難易度：${difficulty}`,W/2,225,27);
    text(`命中数：${hits}`,W/2,285,27,"#5ae6ff");
    text(`ミス数：${misses}`,W/2,330,27,"#ff4b64");
    text(`命中率：${accuracy.toFixed(1)}%`,W/2,375,27);
    buttons.again=button("もう一度",335,445,230,60);
    text("クリックまたはEnterでタイトルに戻る",W/2,535,18,"#9aabc4");
    status.textContent="ゲーム終了";
  }
  function toCanvasPoint(event) {
    const rect=canvas.getBoundingClientRect();
    return {x:(event.clientX-rect.left)*W/rect.width,y:(event.clientY-rect.top)*H/rect.height};
  }
  canvas.addEventListener("pointerdown",event=>{
    initAudio();
    const p=toCanvasPoint(event);
    if(state==="title"){
      if(inside(p,buttons.easy)) difficulty="初級";
      else if(inside(p,buttons.normal)) difficulty="中級";
      else if(inside(p,buttons.hard)) difficulty="上級";
      else if(inside(p,buttons.start)) {startGame();return;}
      drawTitle();
    } else if(state==="playing"){
      if(target && Math.hypot(p.x-target.x,p.y-target.y)<=target.r){
        hits++;playSound("hit");spawnTarget();
      } else {
        misses++;playSound("miss");
        if(misses>=difficulties[difficulty].maxMisses){
          stopBgm();
          state="core";coreStart=performance.now();playSound("overload");
        }
      }
    } else if(state==="result"){
      state="title";drawTitle();
    }
  });
  window.addEventListener("keydown",event=>{
    if(event.key==="Escape"){stopBgm();state="title";drawTitle();}
    if(state==="result" && event.key==="Enter"){state="title";drawTitle();}
  });
  function frame(now){
    if(state==="title") drawTitle();
    else if(state==="countdown") drawCountdown(now);
    else if(state==="playing") drawGame(now);
    else if(state==="core") drawCore(now);
    else if(state==="result") drawResult();
    requestAnimationFrame(frame);
  }
  drawTitle();
  requestAnimationFrame(frame);
})();